from tkinter import ttk

from ..views.acg_view import ViewAcg
from ..utils.logger import logger

from PIL import Image, ImageTk
from pathlib import Path
import os
import re


class NotebookTabs(ttk.Notebook):

    def __init__(self, parent, model, *args, **kwargs):
        super().__init__(parent, name="enb_selector", width=200)
        self.selected_tab_list = []
        self.model = model
        self.icons = self.__get_icons()
        self.enable_custom_config = False
        self._setup()

    def _setup(self):
        self.bind("<<NotebookTabChanged>>", self._handle_tab_change)

        delete_enb_tab_frame = ViewAcg(self, self.model, name="delete_enb_tab")
        self.add(delete_enb_tab_frame, text="", image=self.icons['del_icon'], compound="right")

        refresh_enb_tab_frame = ViewAcg(self, self.model, name="refresh_enb_tab")
        self.add(refresh_enb_tab_frame, text="", image=self.icons['refresh_icon'], compound="right")

        frame_acg = ViewAcg(self, self.model, borderwidth=0, relief="ridge")
        frame_acg.grid(ipady=5)
        self.add(frame_acg, text="eNB 1", image=self.icons['enb_icon'], compound="right")

        add_enb_tab_frame = ViewAcg(self, self.model, name="add_enb_tab")
        self.add(add_enb_tab_frame, text='', image=self.icons['add_icon'], compound="right")
        self.select(2)
        self.selected_tab_list = ['.view_frame.enb_selector.!viewacg']

    def toggle_enable_custom_config(self):
        self.enable_custom_config = not self.enable_custom_config

    # flake8: noqa: C901
    def _handle_tab_change(self, event):
        logger.info(f"Tab {self.select()} selected")
        self.selected_tab_list.append(self.select())
        if re.search(r'viewacg', self.select().split('.')[-1]):
            for k, v in self.children.items():
                if re.search(r'viewacg', k):
                    try:
                        v.unbind_events()
                    except Exception:
                        pass
            self.children[self.select().split('.')[-1]].bind_events()

        elif self.select() == self.tabs()[-1]:  # add_enb
            if self.enable_custom_config:
                self.add_new_enb_tab(enabled=True)
            else:
                # lock adding new enb when custom config is disabled
                self.select(self.selected_tab_list[-2])

        elif self.select() == self.tabs()[0]:  # delete_enb
            if not self.enable_custom_config:
                # when custom config is disabled, lock deleting
                self.select(self.selected_tab_list[-2])
            else:
                if len(self.tabs()) == 4:
                    self.select(2)
                else:
                    self.forget(self.selected_tab_list[-2])
                    self.select(2)
                    self._update_enb_num()

        elif self.select() == self.tabs()[1]:  # reset_enb
            tab = self.children[self.selected_tab_list[-2].split('.')[-1]]
            if self.enable_custom_config:
                # reset to "0"
                self.full_reset(tab)
            else:
                # reset to selected enb basic state
                self.reset(tab)
            self.select(self.selected_tab_list[-2])

    def add_new_enb_tab(self, enabled=False):
        index = len(self.tabs()) - 2
        frame_new = ViewAcg(self, self.model, borderwidth=0, relief="ridge")
        frame_new.grid(ipady=5)
        if enabled:
            frame_new.rmods_frame.custom_enabled = True
        self.insert(index + 1, frame_new, text=f"eNB {index}", image=self.icons['enb_icon'], compound="right")
        self.select(index + 1)

    def reset_tab_view(self):
        for tab in self.tabs():
            if "viewacg" in tab:
                name = tab.split('.')[-1]
                self.children[name].destroy()

    @staticmethod
    def full_reset(tab):
        for children in tab.winfo_children():
            children.reset()

    @staticmethod
    def reset(tab):
        for children in filter(lambda x: 'cell_frame_section' in str(x) or 'rmods_frame_section' in str(x), tab.winfo_children()):
            children.reset()

    def _update_enb_num(self):
        count = 1
        for tab in self.tabs():
            if "viewacg" in tab:
                self.tab(tab, text=f"eNB {count}")
                count += 1

    def __get_icons(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"

        add_icon_resized = Image.open(graphic_src_path / "large_plus.png").convert(mode='RGBA').resize((20, 20), Image.ANTIALIAS)
        add_icon = ImageTk.PhotoImage(add_icon_resized, master=self)

        del_icon_resized = Image.open(graphic_src_path / "large_minus.png").convert(mode='RGBA').resize((20, 20), Image.ANTIALIAS)
        del_icon = ImageTk.PhotoImage(del_icon_resized)

        enb_icon_resized = Image.open(graphic_src_path / "enb_icon.png").convert(mode='RGBA').resize((20, 20), Image.ANTIALIAS)
        enb_icon = ImageTk.PhotoImage(enb_icon_resized)

        refresh_icon_resized = Image.open(graphic_src_path / "refresh_b.png").convert(mode='RGBA').resize((20, 20), Image.ANTIALIAS)
        refresh_icon = ImageTk.PhotoImage(refresh_icon_resized)

        return {
            'add_icon': add_icon,
            'del_icon': del_icon,
            'enb_icon': enb_icon,
            'refresh_icon': refresh_icon,
        }
